class NomTipoPago extends BaseNomTipoPago
{

    /**
     * Obtener un listado de los datos de los tipos de pago.
     *
     * @param int $inicio Inicio de la busqueda.
     * @param int $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los tipos de pago.
     */
    public static function obtenerListadoTiposPago($inicio, $limite, $criterio)
    {

        $where = (!empty($criterio)) ? "tp.denominacion ilike '%" . $criterio . "%'" : 'tp.denominacion is not null';
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->select('tp.*,ctp.denominacion as reporte')
            ->from('NomTipoPago tp')
            ->leftjoin('tp.ConfReportesCertificaciones ctp')
            ->where($where)
            ->orderBy('tp.orden')
            ->limit($limite)
            ->offset($inicio)
            ->fetchArray():
            $query->select('tp.*,ctp.denominacion as reporte')
            ->from('NomTipoPago tp')
            ->leftjoin('tp.ConfReportesCertificaciones ctp')
            ->where($where)
            ->orderBy('tp.orden')
            ->fetchArray();
        return $result;
    }

    /**
     * Obtener un listado de los datos de todos los tipos de pago.
     *
     * @return array    Listado de los datos de los tipos de pago.
     */
    public static function obtenerTodosTiposPago()
    {

        //Devolviendo el listado de tipos de pago en forma de arreglo.
        return Doctrine_Query::create()
            ->from('NomTipoPago')
            ->orderBy('orden')
            ->fetchArray();
    }

    /**
     * Obtener la cantidad total de tipos de pago.
     *
     * @return int      Cantidad total de tipos de pago.
     */
    public static function obtenerCantidadTotalTiposPago()
    {

        //Devolviendo la cantidad total de tipos de pago.
        return Doctrine_Query::create()->select('COUNT(idtipopago) AS cantidad')
            ->from('NomTipoPago')
            ->fetchOne()
            ->cantidad;
    }

    /**
     * Obtener el tipo de pago dado el identificador.
     *
     * @param int $idtipopago Identificador del tipo de pago.
     * @return NomTipoPago      Objeto tipo de pago (clase del dominio).
     */
    public static function obtenerObjTipoPagoDadoId($idtipopago)
    {
        return Doctrine::getTable('NomTipoPago')->find($idtipopago);
    }


    /**
     * Obtener si existe un tipo de pago a partir de la denominaci�n.
     *
     * @param int $idtipop Identificador del tipo de pago.
     * @param string $denom Denominaci�n del tipo de pago.
     *
     * @return boolean                Si existe el tipo de pago.
     */
    public static function existeTipoPago($idtipop, $denom)
    {

        $query = Doctrine_Query::create()->select('COUNT(idtipopago) AS cantidad')
            ->from('NomTipoPago')
            ->where("denominacion ilike ?", $denom);
        if ($idtipop) {
            $query->addWhere('idtipopago <> ?', $idtipop);
        }

        return $query->fetchOne()->cantidad;
    }


    /****************************VER DESDE AQUI*************************************************************/
    public static function existeDenominacionTipoPago($denominacion)
    {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomTipoPago p')
            ->where("p.denominacion=?", array($denominacion))
            ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
            ->execute();
        if (count($result)) {
            return 1;
        } else {
            return 0;
        }
    }

