            ->where('p.idtipopago = ?', array($idtipopago))
            ->fetchOne()
            ->sedesglosa;
    }

    public static function obtenerDenominacion($idtipopago)
    {
        return Doctrine_Query::create()->select('denominacion AS denominacion')
            ->from('NomTipoPago p')
            ->where('idtipopago = ?', array($idtipopago))
            ->fetchOne()
            ->denominacion;
    }

    /**
     * Funcion para verificar si existe el color
     * @param $denom
     * @param $idtiporeunion
     */
    public function findByIdOrDenom($denom, $idtipopago = null)
    {
        try {
            $query = Doctrine_Query::create();
            $query->from('NomTipoPago')
                ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
                ->andWhere("denominacion ilike '$denom'");
            if (!empty($idtipopago)) {
                $query->andWhere("idtipopago <> ?", $idtipopago);
            }
            $result = $query->count();
            if ($result > 0) {
                return true;
            } else {
                return false;
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }

