    public static function obtenerOrdenDisponible()
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sql = "select MAX(orden) as orden from mod_nomina.nom_tipopago";
        $r = $conn->fetchAll($sql);
        $r[0]['orden'] = !empty($r) ? $r[0]['orden'] + 1 : 1;
        return $r[0];
    }

    public static function obtenerValorMismomes($idtipopago)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sql = "SELECT mismomes FROM mod_nomina.nom_tipopago where idtipopago = $idtipopago;";
        $r = $conn->fetchOne($sql);
        return $r[0];
    }

    public static function obtenerListadoTiposPagoArrayId($arrtipospago)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sql = "select * from mod_nomina.nom_tipopago where idtipopago IN (" . implode(',', $arrtipospago) . ") order by orden ASC";
        $r = $conn->fetchAll($sql);
        return $r;
    }

